/**
 * Isometric kit: draws a technical figure as solid parts in an isometric
 * camera and returns SVG markup. It has no dependencies, so it runs in a
 * browser, in Node or in a build script. Colours come from the project's
 * design system through CSS variables. [BD-1143]
 *
 * Read get-illustration-guide({ topic: "isometric-kit" }) before using it.
 *
 * The web app does not import it: this file is the source of the registry
 * item that users install, built by packages/mcp/src/lib/generate-illustration-registry.ts.
 */

/** A point in world units: x and y on the floor, z up. */
export type Vec3 = readonly [number, number, number];

/** How the world maps onto the card. Angles are in degrees. */
export interface Camera {
  azimuth: number;
  elevation: number;
  scale: number;
  offsetX: number;
  offsetY: number;
}

/** A fill for a face, a dot or a shadow. Each one is a class in `ISO_STYLE`. */
export type FillTone = "top" | "shade-0" | "shade-1" | "shade-2" | "shade-3" | "round" | "accent" | "ink" | "halo";

/** A stroke for a line or an outline, strongest first. */
export type LineTone = "line-hi" | "line-mid" | "line-lo" | "line-faint";

/** One drawn path. Larger `depth` is nearer the viewer, so it paints later. */
export type Part =
  | { d: string; tone: FillTone; depth: number; edge?: LineTone }
  | { d: string; tone: LineTone; depth: number };

/** A named group of parts. Layers paint in the order given; parts inside one sort by depth. */
export interface Layer {
  id: string;
  parts: Part[];
}

const RAD = Math.PI / 180;
const r2 = (n: number) => Math.round(n * 100) / 100;

/** A camera at 45 degrees azimuth and 30 degrees elevation unless told otherwise. */
export function camera(azimuth = 45, elevation = 30): Camera {
  return { azimuth, elevation, scale: 1, offsetX: 0, offsetY: 0 };
}

/** A world point placed on the card. Larger `depth` is nearer the viewer. */
export interface CardPoint {
  x: number;
  y: number;
  depth: number;
}

/** Projects a world point to card coordinates, with its depth toward the viewer. */
export function project(cam: Camera, [x, y, z]: Vec3): CardPoint {
  const a = cam.azimuth * RAD;
  const e = cam.elevation * RAD;
  const across = x * Math.cos(a) - y * Math.sin(a);
  const along = x * Math.sin(a) + y * Math.cos(a);
  return {
    x: across * cam.scale + cam.offsetX,
    y: (along * Math.sin(e) - z * Math.cos(e)) * cam.scale + cam.offsetY,
    depth: along * Math.cos(e) + z * Math.sin(e),
  };
}

/** Scales and centres the camera so the points fill `fill` of the card, 0.6 by default. */
export function fit(cam: Camera, points: Vec3[], width: number, height: number, fill = 0.6): Camera {
  const base = { ...cam, scale: 1, offsetX: 0, offsetY: 0 };
  const xs = points.map((p) => project(base, p));
  const minX = Math.min(...xs.map((p) => p.x));
  const maxX = Math.max(...xs.map((p) => p.x));
  const minY = Math.min(...xs.map((p) => p.y));
  const maxY = Math.max(...xs.map((p) => p.y));
  const scale = Math.min((width * fill) / (maxX - minX || 1), (height * fill) / (maxY - minY || 1));
  return {
    ...base,
    scale,
    offsetX: width / 2 - ((minX + maxX) / 2) * scale,
    offsetY: height / 2 - ((minY + maxY) / 2) * scale,
  };
}

/** The direction toward the viewer, in world space. */
function towardViewer(cam: Camera): Vec3 {
  const a = cam.azimuth * RAD;
  const e = cam.elevation * RAD;
  return [Math.sin(a) * Math.cos(e), Math.cos(a) * Math.cos(e), Math.sin(e)];
}

/** Picks a side tone from how far a face turns away from a light at the viewer's upper left. */
function sideTone(cam: Camera, normal: Vec3): FillTone {
  const a = cam.azimuth * RAD;
  const lit = -Math.cos(a) * normal[0] + Math.sin(a) * normal[1];
  if (lit > 0.35) return "shade-0";
  if (lit > -0.35) return "shade-1";
  if (lit > -0.8) return "shade-2";
  return "shade-3";
}

function pathOf(cam: Camera, points: Vec3[], close = true): string {
  const d = points
    .map((p, i) => {
      const s = project(cam, p);
      return `${i ? "L" : "M"}${r2(s.x)} ${r2(s.y)}`;
    })
    .join("");
  return close ? `${d}Z` : d;
}

function centreDepth(cam: Camera, points: Vec3[]): number {
  return points.reduce((sum, p) => sum + project(cam, p).depth, 0) / points.length;
}

/** A box standing on z with its corner at x, y. Returns the faces the camera sees, shaded by facing. */
export function box(
  cam: Camera,
  b: { x: number; y: number; z?: number; w: number; d: number; h: number },
  opts: { accent?: boolean; edge?: LineTone } = {},
): Part[] {
  const { x, y, w, d, h } = b;
  const z = b.z ?? 0;
  const corner = (i: number, j: number, k: number): Vec3 => [x + i * w, y + j * d, z + k * h];
  const faces: Array<{ normal: Vec3; points: Vec3[] }> = [
    { normal: [0, 0, 1], points: [corner(0, 0, 1), corner(1, 0, 1), corner(1, 1, 1), corner(0, 1, 1)] },
    { normal: [1, 0, 0], points: [corner(1, 0, 0), corner(1, 1, 0), corner(1, 1, 1), corner(1, 0, 1)] },
    { normal: [-1, 0, 0], points: [corner(0, 0, 0), corner(0, 1, 0), corner(0, 1, 1), corner(0, 0, 1)] },
    { normal: [0, 1, 0], points: [corner(0, 1, 0), corner(1, 1, 0), corner(1, 1, 1), corner(0, 1, 1)] },
    { normal: [0, -1, 0], points: [corner(0, 0, 0), corner(1, 0, 0), corner(1, 0, 1), corner(0, 0, 1)] },
  ];
  const view = towardViewer(cam);
  const depth = centreDepth(cam, faces.flatMap((f) => f.points));
  return faces
    .filter((f) => f.normal[0] * view[0] + f.normal[1] * view[1] + f.normal[2] * view[2] > 1e-6)
    .map((f) => ({
      d: pathOf(cam, f.points),
      tone: opts.accent ? "accent" : f.normal[2] === 1 ? "top" : sideTone(cam, f.normal),
      depth,
      edge: opts.edge ?? "line-mid",
    }));
}

/** An upright cylinder on z, centred on cx, cy. Its side shades smoothly through the `round` gradient. */
export function cylinder(
  cam: Camera,
  c: { cx: number; cy: number; z?: number; r: number; h: number },
  opts: { accent?: boolean; edge?: LineTone; segments?: number } = {},
): Part[] {
  const z = c.z ?? 0;
  const n = opts.segments ?? 48;
  const ring = (zz: number) =>
    Array.from({ length: n }, (_, i): Vec3 => {
      const t = (i / n) * Math.PI * 2;
      return [c.cx + c.r * Math.cos(t), c.cy + c.r * Math.sin(t), zz];
    });
  const bottom = ring(z);
  const top = ring(z + c.h);
  // The silhouette runs along the near half of the bottom ring and back along the top ring.
  const view = towardViewer(cam);
  // The silhouette's ends are the exact tangent points, so the side is as wide as the top.
  const a = cam.azimuth * RAD;
  const tangent = (sign: number): Vec3 => [c.cx + sign * c.r * Math.cos(a), c.cy - sign * c.r * Math.sin(a), z];
  const near = [
    tangent(-1),
    ...bottom.filter((p) => (p[0] - c.cx) * view[0] + (p[1] - c.cy) * view[1] > 1e-9),
    tangent(1),
  ];
  const sorted = near.sort((p, q) => project(cam, p).x - project(cam, q).x);
  const side = [...sorted, ...sorted.map((p): Vec3 => [p[0], p[1], z + c.h]).reverse()];
  const depth = centreDepth(cam, [...bottom, ...top]);
  const edge = opts.edge ?? "line-mid";
  return [
    { d: pathOf(cam, side), tone: opts.accent ? "accent" : "round", depth, edge },
    { d: pathOf(cam, top), tone: opts.accent ? "accent" : "top", depth: depth + 1e-3, edge },
  ];
}

/** A line between two world points. Make both ends land on a part. */
export function line(cam: Camera, from: Vec3, to: Vec3, tone: LineTone = "line-mid"): Part {
  return { d: pathOf(cam, [from, to], false), tone, depth: centreDepth(cam, [from, to]) };
}

/** Screw heads or terminals: small dots at world points, each with a radius of `r` world units. */
export function dots(cam: Camera, points: Vec3[], r = 0.5, tone: FillTone = "ink"): Part[] {
  return points.map((p) => {
    const s = project(cam, p);
    const rr = r2(r * cam.scale);
    return {
      d: `M${r2(s.x - rr)} ${r2(s.y)}a${rr} ${rr} 0 1 0 ${r2(rr * 2)} 0a${rr} ${rr} 0 1 0 ${r2(-rr * 2)} 0Z`,
      tone,
      depth: s.depth,
    };
  });
}

/** A soft floor shadow under a footprint, drawn first so everything stands on it. */
export function halo(cam: Camera, f: { x: number; y: number; w: number; d: number; z?: number }, spread = 6): Part {
  const z = f.z ?? 0;
  const pts: Vec3[] = [
    [f.x - spread, f.y - spread, z], [f.x + f.w + spread, f.y - spread, z],
    [f.x + f.w + spread, f.y + f.d + spread, z], [f.x - spread, f.y + f.d + spread, z],
  ];
  return { d: pathOf(cam, pts), tone: "halo", depth: -Infinity };
}

/**
 * The style block every figure carries. Paper, ink and accent read the design
 * system's card, foreground and primary tokens, with neutral fallbacks, and the
 * shade steps are mixes of the two, so light and dark themes both work. A page
 * whose tokens are not full colours sets `--iso-paper`, `--iso-ink` and
 * `--iso-accent` instead.
 */
export const ISO_STYLE = `.iso-figure{--iso-p:var(--iso-paper,var(--card,oklch(0.99 0.004 84)));--iso-i:var(--iso-ink,var(--foreground,oklch(0.24 0.01 84)));--iso-a:var(--iso-accent,var(--primary,oklch(0.55 0.16 255)))}
.iso-top{fill:color-mix(in oklch,var(--iso-p) 99%,var(--iso-i))}
.iso-shade-0{fill:color-mix(in oklch,var(--iso-p) 94%,var(--iso-i))}
.iso-shade-1{fill:color-mix(in oklch,var(--iso-p) 88%,var(--iso-i))}
.iso-shade-2{fill:color-mix(in oklch,var(--iso-p) 82%,var(--iso-i))}
.iso-shade-3{fill:color-mix(in oklch,var(--iso-p) 76%,var(--iso-i))}
.iso-accent{fill:var(--iso-a)}
.iso-ink{fill:var(--iso-i)}
.iso-halo{fill:var(--iso-i);opacity:0.06}
.iso-r0{stop-color:color-mix(in oklch,var(--iso-p) 80%,var(--iso-i))}
.iso-r1{stop-color:color-mix(in oklch,var(--iso-p) 98%,var(--iso-i))}
.iso-r2{stop-color:color-mix(in oklch,var(--iso-p) 86%,var(--iso-i))}
.iso-r3{stop-color:color-mix(in oklch,var(--iso-p) 74%,var(--iso-i))}
.iso-figure path{stroke-width:0.75;stroke-linejoin:round;stroke-linecap:round}
.iso-line-hi{stroke:var(--iso-i);fill:none}
.iso-line-mid{stroke:color-mix(in oklch,var(--iso-i) 70%,var(--iso-p));fill:none}
.iso-line-lo{stroke:color-mix(in oklch,var(--iso-i) 45%,var(--iso-p));fill:none}
.iso-line-faint{stroke:color-mix(in oklch,var(--iso-i) 25%,var(--iso-p));fill:none}
.iso-edge-line-hi{stroke:var(--iso-i)}
.iso-edge-line-mid{stroke:color-mix(in oklch,var(--iso-i) 70%,var(--iso-p))}
.iso-edge-line-lo{stroke:color-mix(in oklch,var(--iso-i) 45%,var(--iso-p))}
.iso-edge-line-faint{stroke:color-mix(in oklch,var(--iso-i) 25%,var(--iso-p))}`;

/** Paints the layers into one SVG string, far to near inside each layer. */
export function toSvg(
  layers: Layer[],
  o: { width: number; height: number; title: string; id?: string },
): string {
  const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  // Ids are global to the page, so each figure names its gradient: by `id`, else by its title.
  const slug = (o.id ?? o.title).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  if (!slug) throw new Error("toSvg needs an id with Latin letters or digits, so two figures on one page do not share a gradient.");
  const round = `iso-round-${slug}`;
  const groups = layers
    .map(({ id, parts }) => {
      const paths = [...parts]
        .sort((p, q) => p.depth - q.depth)
        .map((s) => {
          const cls = "edge" in s && s.edge ? `iso-${s.tone} iso-edge-${s.edge}` : `iso-${s.tone}`;
          // A style block may not reach a url, so the gradient fill is an attribute.
          const fill = s.tone === "round" ? ` fill="url(#${round})"` : "";
          return `<path class="${cls}"${fill} d="${s.d}"/>`;
        })
        .join("");
      return `<g id="${esc(id)}">${paths}</g>`;
    })
    .join("");
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${o.width} ${o.height}">` +
    `<title>${esc(o.title)}</title><style>${ISO_STYLE}</style>` +
    // The gradient sits inside the figure group, so its stops inherit the colour variables.
    `<g class="iso-figure"><defs><linearGradient id="${round}"><stop offset="0" class="iso-r0"/>` +
    `<stop offset="0.3" class="iso-r1"/><stop offset="0.7" class="iso-r2"/><stop offset="1" class="iso-r3"/>` +
    `</linearGradient></defs>${groups}</g></svg>`
  );
}
